--
-- Triggers `departmentrequisitionhx`
--
DELIMITER $$
CREATE TRIGGER `updateDepartmentStocks` AFTER INSERT ON `departmentrequisitionhx` FOR EACH ROW BEGIN

-- Declare variables for stock count 
  DECLARE stock_count INT;
  
  
  SELECT COUNT(*) INTO stock_count
  FROM departmentstocks
  WHERE stockid = NEW.stockid AND deptid = NEW.departmentid;


   -- Update department main stocks if stock_count is greater than 0
    IF stock_count > 0 THEN
      -- Stockid exists, update the quantityAvailable in departmentstocks
      UPDATE departmentstocks
      SET quantityAvailable = NEW.qty + quantityAvailable
      WHERE stockid = NEW.stockid AND deptid = NEW.departmentid;
    ELSE
      -- Stockid doesn't exist, insert a new record in departmentstocks
      INSERT INTO departmentstocks (stockid, quantityAvailable, deptid)
      VALUES (NEW.stockid, NEW.qty, NEW.departmentid);
    END IF;

END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `updateGeneralStoreDebit` AFTER INSERT ON `departmentrequisitionhx` FOR EACH ROW BEGIN
  INSERT INTO  generalstoredebithx(stockid,brandid,batchnumber,
debitqty,departmentid,debitdate) 
VALUES(NEW.stockid,NEW.brandid,NEW.batchnumber,NEW.qty,
       NEW.departmentid,NEW.receivedon);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `updateMainstocksSupplyTable` AFTER INSERT ON `departmentrequisitionhx` FOR EACH ROW BEGIN
  -- Declare variables for stock count and batch availability
  DECLARE batchAvailable INT;
  -- Check if a batch is available in departmentconsumption
  SELECT COUNT(*) INTO batchAvailable
  FROM departmentsmainsupply WHERE stockid = NEW.stockid 
  AND departmentid = NEW.departmentid AND batchnumber = NEW.batchnumber;

  -- If department received the item and the quantity received is greater than 0
  IF NEW.status = 'received' THEN
    -- Update department consumption if a batch is available
    IF batchAvailable > 0 THEN 
      -- Update the quantity in departmentmainsupply table
      UPDATE departmentsmainsupply SET
      quantity = NEW.qty + quantity
      WHERE stockid = NEW.stockid AND
      departmentid = NEW.departmentid AND batchnumber = NEW.batchnumber; 
ELSE 
      INSERT INTO departmentsmainsupply (quantity, stockid, departmentid, batchnumber, brand) 
      VALUES (NEW.qty, NEW.stockid, NEW.departmentid, NEW.batchnumber, NEW.brandid);
    END IF;
    END IF;
END
$$
DELIMITER ;

