--
-- Triggers `generalstorecredithx`
--
DELIMITER $$
CREATE TRIGGER `updateMainStockSupply` AFTER INSERT ON `generalstorecredithx` FOR EACH ROW BEGIN 
DECLARE counter INT;

SELECT COUNT(*) INTO counter FROM mainstoresupply WHERE stockid = NEW.stockid AND brandid = NEW.brandid AND batchnumber = NEW.batchnumber;
   -- update mainsupply
    IF counter > 0 THEN 
    UPDATE mainstoresupply SET quantity = NEW.credit + quantity WHERE stockid = NEW.stockid AND brandid = NEW.brandid AND batchnumber = NEW.batchnumber;
    ELSE 
    INSERT INTO mainstoresupply (stockid,brandid,quantity,batchnumber) VALUES (NEW.stockid,NEW.brandid,NEW.credit,NEW.batchnumber);
   END IF;
      -- update generalstocks 
    UPDATE generalstocks  SET quantity = quantity + NEW.credit,updatedOn = NOW() WHERE stockid = NEW.stockid;
END
$$
DELIMITER ;

