CREATE TRIGGER `updateDepartmentRequisitionhx` AFTER UPDATE ON `stocksesrow` FOR EACH ROW BEGIN 

IF NEW.status = 'received' THEN 
  INSERT INTO departmentrequisitionhx(stockid,brandid,batchnumber,
  status,qty,requisitionid,receivedon,departmentid) VALUES(
